import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult} from './SlotMain';
interface HoldRules {caption:string;threshold:number;adjacentReset?:boolean;intervention?:'king'|'sumo'|'train';}
/** Prize holds share only locking/counter arithmetic; subclasses select distinct
 * triggers, collector intervention, progression and bonus-board choreography. */
export function coinHold(s:ExpansionSlot,board:string[],bet:number,rng:()=>number,rules:HoldRules):SpinResult {
 const coins=cells(board,s.id('scatter')),base=s.ordinary(board,bet);if(coins.length<rules.threshold)return s.finish([base]);
 base.expansionFeature!.frames.push(s.frame(board,'trigger',coins.length+' / '+rules.threshold+' 코인 · '+rules.caption,coins));
 const locked=new Map<number,number>();coins.forEach(c=>locked.set(c,[.5,1,2,5][ri(rng,4)]));const bonus=board.map(()=>s.id(7));locked.forEach((v,c)=>bonus[c]=s.id('coin'));
 const rounds=[base],entry=[s.frame(board,'state','트리거 강조 후 보너스판 전환',coins),s.frame(bonus,'effect','고정 코인 재배치',coins,{values:bonus.map((_,c)=>locked.get(c)||0),held:coins,remaining:3})];rounds.push(s.round(bet,entry));let remaining=3,played=0;
 while(remaining>0&&locked.size<board.length&&played<60){remaining--;played++;const prior=[...locked.keys()],landed:number[]=[],before=[...bonus];
  for(let c=0;c<bonus.length;c++)if(!locked.has(c)&&rng()<.075){landed.push(c);bonus[c]=s.id('coin');}
  const resets=landed.some(c=>!rules.adjacentReset||prior.some(p=>Math.abs(p%5-c%5)+Math.abs(Math.floor(p/5)-Math.floor(c/5))===1));
  const frames=[s.frame(before,'reels','고정 코인 유지 · 빈칸 리스핀',[],{held:prior,remaining}),s.frame(bonus,'trigger','새 코인 '+landed.length+'개 착지',landed,{held:prior,remaining})];
  landed.forEach(c=>locked.set(c,[.5,1,2,5,10][ri(rng,5)]));if(resets)remaining=3;
  frames.push(s.frame(bonus,'reveal',resets?'새 코인 → RESPINS 3회 복구':rules.adjacentReset?'인접 착지만 3회 복구':'남은 '+remaining+'회',landed,{held:[...locked.keys()],values:bonus.map((_,c)=>locked.get(c)||0),remaining}));
  if(landed.length&&rules.intervention==='king'){const target=landed[ri(rng,landed.length)],beforeValue=locked.get(target)!;frames.push(s.frame(bonus,'trigger','석조 왕 · 새 코인 승급',[target]));locked.set(target,beforeValue*2);frames.push(s.frame(bonus,'effect','왕의 코인 ×2',[target],{values:bonus.map((_,c)=>locked.get(c)||0),remaining}));}
  if(landed.length&&rules.intervention==='sumo'){const target=landed[ri(rng,landed.length)];frames.push(s.frame(bonus,'trigger','중앙 스모 발구름',landed));locked.set(target,locked.get(target)!+1);frames.push(s.frame(bonus,'effect','발구름 · 코인 상금 +1배',[target],{values:bonus.map((_,c)=>locked.get(c)||0),remaining}));}
  if(landed.length&&rules.intervention==='train'&&played%3===0){frames.push(s.frame(bonus,'trigger','코인 특급 정차',landed));for(const c of landed)locked.set(c,locked.get(c)!*2);frames.push(s.frame(bonus,'effect','정차 코인 배수 ×2',landed,{values:bonus.map((_,c)=>locked.get(c)||0),remaining}));}
  rounds.push(s.round(bet,frames,{heldAtStart:prior.map(cell=>({cell,symbol:s.id('coin'),value:locked.get(cell)!}))}));
 }
 const payoutFrames=[s.frame(bonus,'state',locked.size===bonus.length?'보너스판 완성 · 최종 수집':'리스핀 종료 · 최종 수집',[],{values:bonus.map((_,c)=>locked.get(c)||0),remaining:0})];
 for(const [cell,value]of locked)payoutFrames.push(s.prize(bonus,bet,value,[cell],'고정 코인 한 번 지급'));
 if(locked.size===bonus.length)payoutFrames.push(s.frame(bonus,'trigger','전칸 완성 JACKPOT'),s.prize(bonus,bet,25,[...locked.keys()],'전칸 완성 상금'));
 rounds.push(s.round(bet,payoutFrames));return s.finish(rounds);
}
export class HeartLinkSlot extends ExpansionSlot {play(b:string[],bet:number,rng:()=>number){return coinHold(this,b,bet,rng,{caption:'하트 연결',threshold:3,adjacentReset:true});}}
export class LanternFireSlot extends ExpansionSlot {
 play(b:string[],bet:number,rng:()=>number){const fire=cells(b,this.id('scatter')),lanterns=cells(b,this.id(0));let result=coinHold(this,b,bet,rng,{caption:'불꽃 고정',threshold:4});if(lanterns.length<3)return result;const rounds=result.rounds||[result];rounds[rounds.length-1].expansionFeature!.frames.push(this.frame(b,'trigger','등불 3개 · 별도 무료 8회',lanterns));for(let left=7;left>=0;left--){const after=this.draw(bet,rng),r=this.ordinary(after,bet,'등불 무료 회전');r.freeSpinsRemaining=left;rounds.push(r);}return this.finish(rounds,{freeSpinsAwarded:8,featureOnly:false});}
}
export class CityLinkedSlot extends ExpansionSlot {
 play(b:string[],bet:number,rng:()=>number){const state=[...(this.progress['city-linked-prize:'+bet]||[0])],before=state[0],found=cells(b,this.id('scatter')),fs=[this.frame(b,'reels','연결 도시 코인 착지'),this.hit(b,bet)];state[0]=Math.min(999,state[0]+found.length);if(found.length)fs.push(this.frame(b,'collect','코인 → 여러 슬롯 공유 상금',found,{meter:{label:'연결 상금',before,after:state[0],target:30,items:found.map(cell=>({cell,value:1}))}}));if(state[0]>=30&&found.length>=3){fs.push(this.frame(b,'trigger','공유 적립 30개 + 이번 코인 3개',found),this.prize(b,bet,state[0]*.25,found,'개인 연결 JACKPOT 지급'));state[0]=0;}return this.progressResult(this.finish([this.round(bet,fs)]),bet,state,'city-linked-prize');}
}
/** Linked reserve is personal and wager-specific, persisted through the existing
 * receipt. No server jackpot or shared-account balance is claimed. */
abstract class LinkedCoinSlot extends ExpansionSlot {
 protected linked(r:SpinResult,b:string[],bet:number){const saved=[...(this.progress['city-linked-prize:'+bet]||[0])],before=saved[0],found=cells(b,this.id('scatter'));saved[0]=Math.min(999,saved[0]+found.length);const base=(r.rounds||[r])[0];if(found.length)base.expansionFeature!.frames.push(this.frame(b,'collect','트리거 코인 → 연결 도시 적립',found,{meter:{label:'연결 상금',before,after:saved[0],target:30,items:found.map(cell=>({cell,value:1}))}}));return this.progressResult(r,bet,saved,'city-linked-prize');}
}
export class CoinRailSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){return this.linked(coinHold(this,b,bet,rng,{caption:'Coin Grab 특급',threshold:3,intervention:'train'}),b,bet);}}
export class SilverMineSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){return this.linked(coinHold(this,b,bet,rng,{caption:'은광 Prize Coin 보드',threshold:3}),b,bet);}}
export class OilPrizeSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){return this.linked(coinHold(this,b,bet,rng,{caption:'유전 상금 수집 후 금고 전환',threshold:3}),b,bet);}}
export class StoneKingSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){return this.linked(coinHold(this,b,bet,rng,{caption:'석조 왕 코인 금고',threshold:3,intervention:'king'}),b,bet);}}
export class DragonEmberSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){const result=coinHold(this,b,bet,rng,{caption:'용 불씨 별도 보너스판',threshold:3});return this.linked(result,b,bet);}}
export class SumoRingSlot extends LinkedCoinSlot {play(b:string[],bet:number,rng:()=>number){return this.linked(coinHold(this,b,bet,rng,{caption:'스모 원형 금고',threshold:3,intervention:'sumo'}),b,bet);}}
