import {SlotMain,SlotConfig,SpinResult,Win,CellDrop} from './SlotMain';
import {BET_LEVELS} from './BetLevels';import {WOLF_LINES} from './WolfRules';
import {SlotProgress,normalizeSlotProgress,socialPresentation,awardLines} from './Social2230Rules';
export const JEWEL_ID='seven-jewel-dig';
export const JEWEL_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]].map(row=>row.map(n=>n*1.3002));
export const JEWEL_PRIZES=[1,1.5,2,3,4,5,0];
export interface JewelEvent {cell:number;jewel:number;before:number[];after:number[];matched:boolean;award?:Win;}
export interface JewelStage {board:string[];lineWins:Win[];removed:number[];gems:JewelEvent[];drops:CellDrop[];afterBoard:string[];}
export interface JewelPlayback {before:number[];after:number[];stages:JewelStage[];}
export class SevenJewelSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;
 private progress:SlotProgress={};setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 readonly presentation=socialPresentation('텀블 빈자리 보석 · 같은 종류 세 개 수집','일곱 보석 상자');
 readonly config:SlotConfig={id:JEWEL_ID,title:'일곱 보석 발굴단',subtitle:'SEVEN JEWEL DIG',tag:'JEWEL MATCH COLLECTION',color:'#373d35',accent:'#e7c583',description:'5×3 · 25라인 · 왼쪽부터3개 이상\n당첨 심볼은 사라지고 위 심볼이 낙하하여 다시 판정합니다.\n비워진 칸의 숨은 보석을 별도 상자에 수집합니다.\n같은 보석3개면 해당 보석만 비우고 보상을 지급합니다.\n청록 보석3개는 베팅2/5/10배 미스터리 보상. 다른 보석1/1.5/2/3/4/5배.\n보석 상자는 베팅별 저장. 별도 프리스핀 없음.',symbols:['발굴 횃불','석조 나침반','발굴 붓','점토 항아리','밧줄 묶음','접힌 지도','고대 동전','발굴 가방','황금 가면 WILD','보물 상자'].map((name,i)=>({id:JEWEL_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#e7c583',weight:[5,6,7,8,10,12,14,16,2,4][i],payout:i<8?JEWEL_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult{if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid jewel board');const wins=awardLines(this.config,board,bet,JEWEL_PAYS);return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};}
 resolve(initial:string[],bet:number,rng:()=>number):SpinResult {
  this.evaluate(initial,bet);const before=[...(this.progress[JEWEL_ID+':'+bet]||[0,0,0,0,0,0,0])],after=[...before],stages:JewelStage[]=[],wins:Win[]=[];let board=[...initial],paid=0;
  const add=(w:Win)=>{w.amount=Math.min(w.amount,bet*this.maxWin-paid);paid+=w.amount;wins.push(w);};
  for(let step=0;step<1000;step++){
   const r=this.evaluate(board,bet),removed=Array.from(new Set(r.wins.flatMap(w=>w.cells))),gems:JewelEvent[]=[],drops:CellDrop[]=[];r.wins.forEach(add);
   for(const cell of removed){if(rng()>=.12)continue;const jewel=Math.floor(rng()*7),previous=[...after];after[jewel]++;const matched=after[jewel]===3;let award:Win|undefined;if(matched){after[jewel]=0;const mult=jewel===6?[2,5,10][Math.floor(rng()*3)]:JEWEL_PRIZES[jewel];award={line:-1,symbol:JEWEL_ID+'-jewel-'+jewel,cells:[cell],amount:Math.round(bet*mult)};add(award);}gems.push({cell,jewel,before:previous,after:[...after],matched,award});}
   const next=[...board];if(removed.length&&paid<bet*this.maxWin){for(let col=0;col<5;col++){const survivors=[col+10,col+5,col].filter(c=>!removed.includes(c));for(let row=2;row>=0;row--){const to=row*5+col,from=survivors[2-row]??-1,symbol=from<0?this.pick(rng):board[from];next[to]=symbol;drops.push({to,from,symbol});}}}
   stages.push({board:[...board],lineWins:r.wins,removed,gems,drops,afterBoard:[...next]});board=next;if(!removed.length||paid>=bet*this.maxWin)return{board:[...board],bet,wins,payout:paid,jewelFeature:{before,after,stages},progressUpdate:{key:JEWEL_ID+':'+bet,values:[...after]},presentation:this.presentation};
  }throw Error('Jewel tumble did not converge');
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(Array.from({length:15},()=>this.pick(rng)),bet,rng);}
 demoSpin(bet:number){let seed=380928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<10000;i++){const r=this.spin(bet,rng);if(r.payout)return r;}throw Error('Jewel fixture unavailable');}
}
