import {assetManager,ImageAsset,Rect,resources,Size,SpriteFrame,Texture2D} from 'cc';
import {RUNTIME_ART} from './RuntimeArtManifest';
import {EXPANSION_RUNTIME_ART} from './ExpansionRuntimeArt';

// One in-flight load per atlas: startup may request dozens of frames at once.
const textures=new Map<string,Promise<Texture2D>>();
function loadTexture(path:string,sourceAudit:boolean){
 const key=(sourceAudit?'source:':'bundle:')+path;
 let pending=textures.get(key);
 if(!pending){
  pending=new Promise<Texture2D>((resolve,reject)=>{
   const done=(error:Error|null,texture?:Texture2D)=>{if(error||!texture){reject(error||new Error('Missing texture '+path));return;}texture.setFilters(Texture2D.Filter.NEAREST,Texture2D.Filter.NEAREST);resolve(texture);};
   if(sourceAudit){assetManager.loadRemote<ImageAsset>(new URL('/__source_art__/'+path+'.png',location.href).href,{ext:'.png'},(error,asset)=>{if(error){done(error);return;}const texture=new Texture2D();texture.image=asset;done(null,texture);});}
   else resources.load(path+'/texture',Texture2D,done);
  });
  textures.set(key,pending);pending.catch(()=>{textures.delete(key);});
 }
 return pending;
}
export async function loadRuntimeArt(path:string,sourceAudit=false):Promise<SpriteFrame>{
 const packed=RUNTIME_ART[path]||EXPANSION_RUNTIME_ART[path],texture=await loadTexture(packed?.[0]||path,sourceAudit);
 const frame=new SpriteFrame();frame.texture=texture;
 if(packed){frame.rect=new Rect(packed[1],packed[2],packed[3],packed[4]);frame.originalSize=new Size(packed[3],packed[4]);}
 return frame;
}
