import {SpinResult,Win,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,TumbleTile,indices,adjacent,randomIndex} from './TumbleCore';

export const HEX_CELLS=Array.from({length:49},(_,c)=>c).filter(c=>{const q=c%7-3,r=Math.floor(c/7)-3;return Math.max(Math.abs(q),Math.abs(r),Math.abs(q+r))<=3;});
export const HEX_RINGS=[1,2,3].map(radius=>HEX_CELLS.filter(c=>{const q=c%7-3,r=Math.floor(c/7)-3;return Math.max(Math.abs(q),Math.abs(r),Math.abs(q+r))===radius;}).sort((a,b)=>Math.atan2(Math.floor(a/7)-3,a%7-3+(Math.floor(a/7)-3)/2)-Math.atan2(Math.floor(b/7)-3,b%7-3+(Math.floor(b/7)-3)/2)));
export const hexNeighbors=(c:number)=>[c-1,c+1,c-7,c+7,c-6,c+6].filter(n=>HEX_CELLS.includes(n)&&Math.abs(n%7-c%7)<=1&&Math.abs(Math.floor(n/7)-Math.floor(c/7))<=1);
export const HEX_TILES:TumbleTile[]=HEX_CELLS.map(cell=>({cell,x:cell%7+.5+(Math.floor(cell/7)-3)/2,y:Math.floor(cell/7)+.5,w:.9,h:.9}));
export class OrbitalCrystalSlot extends TumbleGame {
 readonly columns=7;readonly rows=7;readonly hasBonus=true;
 readonly config=this.configFor('orbital-crystal-core','궤도 수정핵','ORBITAL CRYSTAL CORE',['붉은 운석','황색 운석','초록 운석','청색 운석','보라 운석','흰 운석','중력 WILD','궤도 신호'],['0','1','2','3','4','5','wild','scatter'],'육각3링 · 연결6개. 당첨 뒤 링 회전. WILD는 중심으로 이동·흡수되어 배수 +1. 회전 Spot이 고정 Zone과 만나면 링 변환, Zone의 신호는 무료5회(총30회 상한).');
 readonly threshold=6;
 private roll(input:string[],bet:number,rng:()=>number,bank:{multi:number;spots:number[]},free:boolean){
  let board=[...input];for(let c=0;c<49;c++)if(!HEX_CELLS.includes(c))board[c]=this.id('void');board[24]=this.wild!;
  const frames:TumbleFrame[]=[],options=()=>({tiles:HEX_TILES,badges:{24:'×'+bank.multi},marks:HEX_RINGS.map(r=>r[0])});let bonus=0;
  this.frame(frames,board,'land',free?'궤도 무료 · 중심 배수 유지':'궤도 수정 착지',{...options(),stationary:[24]});
  for(let step=0;step<30;step++){
   const wins=this.clusters(board,bet,bank.multi,hexNeighbors,6);if(!wins.length)break;
   const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>board[c]!==this.wild));this.frame(frames,board,'win','수정 클러스터 ×'+bank.multi,{...options(),wins,cells:Array.from(remove)});
   const next=this.gravity(board,remove,rng,new Set(indices(board,this.wild!)));board=next.board;this.frame(frames,board,'drop','육각 궤도 보충',{...options(),moves:next.moves});
   const before=[...board],moves:CellDrop[]=[];
   HEX_RINGS.forEach((ring,i)=>{ring.forEach((from,j)=>{const to=ring[(j+1)%ring.length];board[to]=before[from];moves.push({from,to,symbol:before[from]});});bank.spots[i]=(bank.spots[i]+1)%ring.length;});
   this.frame(frames,board,'move','세 링 회전',{...options(),moves});
   // Nearest first; a token moves at most one ring each cascade.
   const tokens=indices(board,this.wild!).filter(c=>c!==24).sort((a,b)=>HEX_RINGS.findIndex(r=>r.includes(a))-HEX_RINGS.findIndex(r=>r.includes(b)));
   for(const from of tokens){if(board[from]!==this.wild)continue;const ring=HEX_RINGS.findIndex(r=>r.includes(from));
    if(ring===0){board[from]=this.pick(rng);bank.multi++;this.frame(frames,board,'collect','중심이 WILD 흡수 · ×'+bank.multi,{...options(),cells:[from,24],moves:[{from,to:24,symbol:this.wild!}]});}
    else{const targets=hexNeighbors(from).filter(c=>HEX_RINGS[ring-1].includes(c)&&board[c]!==this.wild),to=targets[0];if(to!==undefined){const other=board[to];board[to]=this.wild!;board[from]=other;this.frame(frames,board,'move','WILD 한 궤도 안쪽으로',{...options(),moves:[{from,to,symbol:this.wild!},{from:to,to:from,symbol:other}]});}}
   }
   HEX_RINGS.forEach((ring,i)=>{if(bank.spots[i]!==0)return;const symbol=this.id(randomIndex(rng,6)),cells=ring.filter(c=>board[c]!==this.wild);cells.forEach(c=>board[c]=symbol);this.frame(frames,board,'transform','Spot·Zone 정렬 · 링 변환',{...options(),cells});});if(step===29)this.frame(frames,board,'state','연쇄30회 안전 종료',options());
  }
  for(const ring of HEX_RINGS)if(board[ring[0]]===this.bonusSymbol)bonus+=5;
  if(bonus)this.frame(frames,board,'state','Zone 신호 · 무료 +'+bonus,options());return{round:this.round(bet,frames),bonus};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const bank={multi:1,spots:[1,2,3]},base=this.roll(this.draw(rng),bet,rng,bank,false);if(!base.bonus)return this.finish([base.round]);let left=base.bonus,awarded=left;const rounds=[base.round];while(left>0){left--;const next=this.roll(this.draw(rng),bet,rng,bank,true),extra=Math.min(next.bonus,30-awarded);awarded+=extra;left+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:base.bonus});}
}

export class BuriedGateSlot extends TumbleGame {
 readonly columns=6;readonly rows=6;readonly hasBonus=true;readonly bonusChoiceCount=3;
 readonly config=this.configFor('buried-gate-chambers','묻힌 문 세 갈래','BURIED GATE CHAMBERS',['붉은 토기','금빛 인장','초록 잎','청색 항아리','보라 부적','흰 유물','탐험 WILD','봉인 돌'],['0','1','2','3','4','5','wild','stone'],'6×6 · 연결5개. 당첨 옆 봉인 돌 파괴·보드 개방. 돌을 모두 없애면 3경로 선택: 8회×1 / 5회×2 / 3회×4. 무료 중 완전 개방 +2회(총30회). 자체 클러스터 각색.');
 private roll(bet:number,rng:()=>number,multiplier:number,stoneCount:number,input?:string[]){
  let board=input?[...input]:this.draw(rng);if(!input){board=board.map(s=>s===this.id('stone')?this.id(randomIndex(rng,6)):s);const cells=Array.from({length:36},(_,c)=>c);for(let n=0;n<stoneCount;n++){const at=randomIndex(rng,cells.length);board[cells.splice(at,1)[0]]=this.id('stone');}}
  const frames:TumbleFrame[]=[];this.frame(frames,board,'land','봉인 돌 '+indices(board,this.id('stone')).length+'개 · ×'+multiplier);
  for(let step=0;step<30;step++){const wins=this.clusters(board,bet,multiplier);if(!wins.length)break;const removed=new Set(wins.flatMap(w=>w.cells)),stones=indices(board,this.id('stone')).filter(c=>adjacent(c,6,36).some(n=>removed.has(n)));
   this.frame(frames,board,'win','당첨 지급 후 인접 봉인 해체',{wins,cells:Array.from(removed)});stones.forEach(c=>removed.add(c));if(stones.length)this.frame(frames,board,'transform','봉인 돌 '+stones.length+'개 파괴',{cells:stones});
   const next=this.gravity(board,removed,rng,new Set(indices(board,this.id('stone')).filter(c=>!removed.has(c))));board=next.board.map(s=>s===this.id('stone')?this.id(randomIndex(rng,6)):s);
   // Preserve unbroken stones; random incoming stones become regular symbols.
   for(const c of indices(frames[frames.length-1].board,this.id('stone')))if(!removed.has(c))board[c]=this.id('stone');next.moves.forEach(m=>m.symbol=board[m.to]);
   this.frame(frames,board,'drop','돌 사이로 유물 낙하',{moves:next.moves});if(step===29)this.frame(frames,board,'state','연쇄30회 안전 종료');
  }return{round:this.round(bet,frames),clear:!board.includes(this.id('stone'))};
 }
 play(board:string[],bet:number,rng:()=>number){this.check(board,bet);const base=this.roll(bet,rng,1,0,board);return this.complete(base,bet,rng);}
 private complete(base:{round:SpinResult;clear:boolean},bet:number,rng:()=>number){if(!base.clear)return this.finish([base.round]);
  const results=[0,1,2].map(choice=>{const rounds=[structuredClone(base.round)],initial=[8,5,3][choice],multiplier=[1,2,4][choice];let left=initial,awarded=left;
   while(left>0){left--;const next=this.roll(bet,rng,multiplier,3),extra=next.clear?Math.min(2,30-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:initial});});
  return{...results[0],featureChoices:{title:'세 갈래 문',labels:['8회 · ×1','5회 · ×2','3회 · ×4'],results,defaultIndex:0}};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.complete(this.roll(bet,rng,1,3),bet,rng);}
}

export const roseRotation=(c:number)=> (4-c%5)*5+Math.floor(c/5);
export class RoseOrbitSlot extends TumbleGame {
 readonly columns=5;readonly rows=5;readonly hasBonus=true;
 readonly config=this.configFor('rose-orbit-voyage','장미 궤도 항해','ROSE ORBIT VOYAGE',['붉은 장미','금빛 망원경','초록 행성','청색 나침반','보라 운석','흰 달','여우 WILD','궤도 문'],['0','1','2','3','4','5','wild','scatter'],'5×5 · 연결5개. 당첨마다 판을 반시계90도 회전 후 중력 낙하. 2×2 장미가 아래2칸을 누르면 배수 +2. 문3개: 무료6회, 문3개 재발동 +2(총24회).');
 private roll(bet:number,rng:()=>number,free:boolean){let board=this.draw(rng),multi=1;const frames:TumbleFrame[]=[];this.frame(frames,board,'land','장미 궤도 착지');const scatter=indices(board,this.bonusSymbol!).length;let giant:number[]=[];
  if(randomIndex(rng,free?3:7)===0){const x=randomIndex(rng,4),y=randomIndex(rng,3);giant=[y*5+x,y*5+x+1,(y+1)*5+x,(y+1)*5+x+1];giant.forEach(c=>board[c]=this.id(0));const crushed=[(y+2)*5+x,(y+2)*5+x+1];multi+=2;const tiles=board.map((_,cell)=>({cell,x:cell%5+.5,y:Math.floor(cell/5)+.5,w:1,h:1})).filter(t=>!giant.slice(1).includes(t.cell));tiles.find(t=>t.cell===giant[0])!.w=2;tiles.find(t=>t.cell===giant[0])!.h=2;tiles.find(t=>t.cell===giant[0])!.x+=.5;tiles.find(t=>t.cell===giant[0])!.y+=.5;
   this.frame(frames,board,'transform','거대 장미 · 아래 두 심볼 압축 ×'+multi,{cells:crushed,tiles});const n=this.gravity(board,new Set(crushed),rng,new Set(giant));board=n.board;this.frame(frames,board,'drop','압축 빈자리 보충',{moves:n.moves,tiles});this.frame(frames,board,'transform','압축 완료 · 장미 네 칸으로 분리',{cells:giant});}
  for(let step=0;step<30;step++){const wins=this.clusters(board,bet,multi);if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells));this.frame(frames,board,'win','궤도 클러스터 ×'+multi,{wins,cells:Array.from(remove)});
   // Rotate tokens AND holes before applying gravity in the new direction.
   const before=[...board],moves:CellDrop[]=[],rotated=new Set<number>();for(let from=0;from<25;from++){const to=roseRotation(from);board[to]=before[from];moves.push({from,to,symbol:before[from]});if(remove.has(from))rotated.add(to);}
   this.frame(frames,board,'move','판 전체 반시계90도 회전',{moves,cells:Array.from(rotated)});const next=this.gravity(board,rotated,rng);board=next.board;this.frame(frames,board,'drop','새 중력 방향 낙하',{moves:next.moves});if(step===29)this.frame(frames,board,'state','연쇄30회 안전 종료');}
  return{round:this.round(bet,frames),scatter};
 }
 rawSpin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.roll(bet,rng,false);if(base.scatter<3)return this.finish([base.round]);const rounds=[base.round];let left=6,awarded=6;while(left>0){left--;const next=this.roll(bet,rng,true),extra=next.scatter>=3?Math.min(2,24-awarded):0;left+=extra;awarded+=extra;next.round.freeSpinsAdded=extra||undefined;next.round.freeSpinsRemaining=left;rounds.push(next.round);}return this.finish(rounds,{freeSpinsAwarded:6});}
}
