import {isLocalMode} from './LocalMode';
import {collection,doc,getApps,getCountFromServer,getDocs,getFirestore,orderBy,query,serverTimestamp,setDoc,where} from '../vendor/firebase-sdk.js';

export const RECENT_VISITOR_WINDOW_MS=24*60*60*1000;
const VISIT_WRITE_INTERVAL_MS=15*60*1000;
const COUNT_REFRESH_INTERVAL_MS=5*60*1000;
export interface LobbySnapshot {recent24h:Record<string,number>;plays:Record<string,number>;spinTotals:Record<string,number>;best:string|null;popular:string|null;updatedAt:number;}
export function isCocosLocalPreview(locationLike:{hostname:string;port:string}|undefined=typeof location==='undefined'?undefined:location):boolean{return !!locationLike&&['localhost','127.0.0.1'].includes(locationLike.hostname)&&locationLike.port==='7456';}
export function recentVisitorCutoff(now=Date.now()):Date{return new Date(now-RECENT_VISITOR_WINDOW_MS);}
export function shouldRecordVisit(previous:number|undefined,now=Date.now()):boolean{return previous===undefined||now-previous>=VISIT_WRITE_INTERVAL_MS;}
export class LobbyPresence {
 snapshot:LobbySnapshot|null=null;private session='';private slot:string|null=null;private uid='';private timer:any;private sequence=0;private alive=true;private localPreview=false;private lastCountAt=0;private countBusy=false;private popularityBusy=false;private recorded=new Map<string,number>();
 constructor(private slotIds:string[],private changed:()=>void,private browserPresence=true){this.localPreview=isLocalMode()||browserPresence&&isCocosLocalPreview();this.session='pocket-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);if(browserPresence&&!this.localPreview){void this.heartbeat();this.timer=setInterval(()=>void this.heartbeat(),15000);}}
 private async post(route:string,body:object){if(isLocalMode()||!this.browserPresence||isCocosLocalPreview())return;try{const response=await fetch('/api/lobby/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:this.session,...body})});if(response.ok&&this.alive){const live=await response.json(),recent24h=this.snapshot?.recent24h||{},spinTotals=this.snapshot?.spinTotals||{};this.snapshot={recent24h,plays:live.plays||{},spinTotals,best:live.best||null,popular:this.snapshot?.popular||live.popular||null,updatedAt:Number(live.updatedAt)||Date.now()};this.changed();}}catch{}}
 setUser(uid:string|null){const next=uid||'';if(this.uid===next)return;this.uid=next;this.recorded.clear();this.lastCountAt=0;if(next&&!this.localPreview){void this.refreshRecent24h(true);void this.refreshPopularity();}}
 enter(slot:string|null){this.slot=slot;if(!this.localPreview){void this.heartbeat();if(slot)void this.recordVisit(slot);else void this.refreshRecent24h();}}
 private heartbeat(){return this.post('heartbeat',{slot:this.browserPresence&&typeof document!=='undefined'&&document.hidden?null:this.slot});}
 play(){if(!this.localPreview&&this.slot){const slot=this.slot,base=this.snapshot,spinTotals={...(base?.spinTotals||{})};spinTotals[slot]=(spinTotals[slot]||0)+1;this.snapshot={recent24h:base?.recent24h||{},plays:base?.plays||{},spinTotals,best:base?.best||null,popular:Object.entries(spinTotals).sort((a,b)=>b[1]-a[1])[0]?.[0]||null,updatedAt:Date.now()};this.changed();void this.post('play',{slot,round:this.session+'-'+(++this.sequence)});}}
 private firebaseDb(){if(isLocalMode())return null;const app=getApps().find(item=>item.name==='in-my-pocket');return app?getFirestore(app):null;}
 private async recordVisit(slot:string){const db=this.firebaseDb(),uid=this.uid,now=Date.now();if(!db||!uid||!shouldRecordVisit(this.recorded.get(slot),now))return;this.recorded.set(slot,now);try{await setDoc(doc(db,'slotVisitors',slot,'users',uid),{lastSeenAt:serverTimestamp()},{merge:true});}catch{this.recorded.delete(slot);}}
 private async refreshPopularity(){
  const db=this.firebaseDb();if(!db||!this.uid||this.popularityBusy)return;
  this.popularityBusy=true;
  try{
   const snapshot=await getDocs(query(collection(db,'slotPopularity'),orderBy('totalSpins','desc')));
   if(!this.alive)return;
   const spinTotals:Record<string,number>={};
   for(const row of snapshot.docs){const value=Number(row.data().totalSpins);if(this.slotIds.includes(row.id)&&Number.isSafeInteger(value)&&value>=0)spinTotals[row.id]=value;}
   const base=this.snapshot,top=Object.entries(spinTotals)[0];
   this.snapshot={recent24h:base?.recent24h||{},plays:base?.plays||{},spinTotals,best:base?.best||null,popular:top?.[0]||null,updatedAt:Date.now()};
   this.changed();
  }catch{}finally{this.popularityBusy=false;}
 }
 private async refreshRecent24h(force=false){const db=this.firebaseDb(),now=Date.now();if(!db||!this.uid||this.countBusy||(!force&&now-this.lastCountAt<COUNT_REFRESH_INTERVAL_MS))return;this.countBusy=true;try{const cutoff=recentVisitorCutoff(now),entries=await Promise.all(this.slotIds.map(async slot=>{const result=await getCountFromServer(query(collection(db,'slotVisitors',slot,'users'),where('lastSeenAt','>=',cutoff)));return [slot,result.data().count] as const;}));if(!this.alive)return;const recent24h=Object.fromEntries(entries),base=this.snapshot,top=entries.reduce((best,row)=>row[1]>best[1]?row:best,['',0] as readonly [string,number]);this.snapshot={recent24h,plays:base?.plays||recent24h,spinTotals:base?.spinTotals||{},best:base?.best||null,popular:base?.popular||(top[1]>0?top[0]:null),updatedAt:now};this.lastCountAt=now;this.changed();}catch{}finally{this.countBusy=false;}}
 dispose(){clearInterval(this.timer);if(!this.localPreview)void this.post('heartbeat',{slot:null});this.alive=false;}
}
