import type {SpinResult} from './SlotMain';
/** Purchases already contain only free-game rounds. Natural entries retain
 * their paid trigger round, which must not be counted again as a free spin. */
export function bonusCompletion(result:SpinResult,purchased:boolean){
 if(!result.rounds?.length)return null;
 const rounds=(purchased?result.rounds:result.rounds.slice(1)).filter(round=>!round.moonFeature||round.moonFeature.mode==='free');
 if(!rounds.length)return null;
 return{count:rounds.length,payout:rounds.reduce((sum,round)=>sum+round.payout,0)};
}
