import {SpinResult,Win} from './SlotMain';
import {Social2230LineSlot,socialPresentation,awardLines,sumResult} from './Social2230Rules';
export interface CrossroadsPlayback {left:Win[];right:Win[];}
export class FrostFlameSlot extends Social2230LineSlot {
 readonly presentation=socialPresentation('불꽃은 왼쪽부터 · 서리는 오른쪽부터','양방향 라인 당첨');
 readonly config=this.namedConfig('frost-flame-crossroads','서리와 불꽃 교차로','FROST AND FLAME CROSSROADS',['불꽃 횃불','얼음 결정','용 비늘 방패','서리 왕관','화산돌','눈꽃 깃털','불씨 랜턴','얼음 열쇠','교차 문장 WILD'],'25개 경로를 왼쪽과 오른쪽에서 각각 판정합니다.\n같은 5칸 당첨은 한 번만 지급. 서로 다른 끝의 당첨은 둘 다 지급.\n양방향 중 같은 라인·같은 칸 집합은 중복 지급하지 않습니다.\n별도 무료 회전 없음.','#263d52','#aee4f5');
 evaluate(board:string[],bet:number):SpinResult{
  const r=super.evaluate(board,bet),left=r.wins,right=awardLines(this.config,board,bet,this.pays,true).filter(w=>!left.some(l=>l.line===w.line&&l.symbol===w.symbol&&l.cells.length===w.cells.length&&l.cells.every(c=>w.cells.includes(c))));
  r.wins=[...left,...right];r.crossroadsFeature={left,right};return sumResult(r);
 }
 spin(bet:number,rng:()=>number=Math.random){return this.draw(bet,rng);}
 demoSpin(bet:number){const id=this.config.id,b=Array.from({length:15},(_,i)=>id+'-'+(i+Math.floor(i/5))%8);b[5]=b[6]=b[7]=id+'-0';b[2]=b[3]=b[4]=id+'-1';return this.evaluate(b,bet);}
}
