import {winTickets} from './WinTickets';
import {expandedCostumes} from './CostumeExpansion';
import {petCatalog} from './PetCatalog';
import {Win} from '../slots/SlotMain';
export type PerkCondition='hit'|'big'|'super'|'mega'|'amazing'|'streak2'|'streak3'|'five'|'multi'|'four'|'cascade3'|'cascade5'|'comeback'|'small';
export interface Perk {condition:PerkCondition;currency:'coins'|'tickets';bps:number;}
export interface PerkContext {bet:number;payout:number;wins:Win[];columns:number;mode:string;cascades:number;streak:number;misses:number;}
export interface PerkAward {id:string;condition:string;coins:number;tickets:number;pending:boolean;}
export const activePerkSlots=['pet','hair','top','pants','shoes'] as const;
export const NORMAL_COIN_BPS=20,EVENT_COIN_BPS=40,NORMAL_COIN_CAP_BPS=100,EVENT_COIN_CAP_BPS=200;
export const eventCoinConditions:ReadonlySet<PerkCondition>=new Set(['super','mega','amazing','cascade5','comeback']);
const perkSlots:Record<string,string>={'basic-hair':'hair','hair-coral':'hair','hair-silver':'hair',night:'top',ocean:'top',mint:'top','basic-shorts':'pants',denim:'pants','shorts-rose':'pants',sneakers:'shoes','dress-shoes':'shoes'};
for(const item of expandedCostumes)perkSlots[item.id]=item.slot;
for(const pet of petCatalog)perkSlots[pet.id]='pet';
/** Only canonical, active part/item pairs can contribute, once per part. */
export function equippedPerks(equipment:Partial<Record<string,string>>){return activePerkSlots.flatMap(slot=>{const id=equipment[slot];return id&&perkSlots[id]===slot&&costumePerks[id]?[{slot,id,perk:costumePerks[id]}]:[];});}
export const conditionNames:Record<PerkCondition,string>={hit:'히트',big:'10배 이상',super:'30배 이상',mega:'50배 이상',amazing:'100배 이상',streak2:'2연속 히트',streak3:'3연속 히트',five:'같은 심볼 5개',multi:'2개 라인 동시 당첨',four:'4개 라인 동시 당첨',cascade3:'3연쇄 이상',cascade5:'5연쇄 이상',comeback:'3번 미당첨 뒤 히트',small:'베팅 미만 소액 히트'};
// Starter hair, shirt (night), and shorts are cosmetic only and have no perk entry.
export const costumePerks:Record<string,Perk>={
 'hair-coral':{condition:'hit',currency:'coins',bps:100},'hair-silver':{condition:'super',currency:'tickets',bps:1500},cap:{condition:'big',currency:'coins',bps:200},beret:{condition:'streak2',currency:'coins',bps:400},
 shades:{condition:'multi',currency:'coins',bps:250},'shades-pink':{condition:'super',currency:'coins',bps:450},'ear-gold':{condition:'hit',currency:'tickets',bps:500},'ear-star':{condition:'mega',currency:'tickets',bps:2500},
 chain:{condition:'small',currency:'tickets',bps:1000},pendant:{condition:'streak3',currency:'tickets',bps:3000},ocean:{condition:'hit',currency:'coins',bps:75},mint:{condition:'cascade3',currency:'coins',bps:450},
 denim:{condition:'five',currency:'coins',bps:700},'shorts-rose':{condition:'comeback',currency:'coins',bps:600},peach:{condition:'streak2',currency:'tickets',bps:2000},violet:{condition:'cascade5',currency:'tickets',bps:4000},
 gold:{condition:'amazing',currency:'coins',bps:800},rose:{condition:'four',currency:'tickets',bps:3500},ember:{condition:'super',currency:'coins',bps:500},sneakers:{condition:'multi',currency:'tickets',bps:1000},'dress-shoes':{condition:'five',currency:'tickets',bps:3000},
 'pet-cat':{condition:'big',currency:'tickets',bps:1500},'pet-bot':{condition:'cascade3',currency:'tickets',bps:2000}
};
for(const item of expandedCostumes)costumePerks[item.id]={condition:item.condition as PerkCondition,currency:item.currency,bps:item.bps};
export function perkDescription(id:string){const p=costumePerks[id];return p?conditionNames[p.condition]+' · '+(p.currency==='coins'?'코인':'당첨 배수 티켓')+' +'+(p.bps/100)+'%':'특수능력 없음';}
function matches(condition:PerkCondition,c:PerkContext){if(c.payout<=0)return false;const multiple=c.payout/c.bet,lines=c.wins.filter(w=>w.line>=0).length;switch(condition){case 'hit':return true;case 'big':return multiple>=10;case 'super':return multiple>=30;case 'mega':return multiple>=50;case 'amazing':return multiple>=100;case 'streak2':return c.streak>=2;case 'streak3':return c.streak>=3;case 'five':return c.mode==='lines'&&c.columns>=5&&c.wins.some(w=>w.line>=0&&w.cells.length>=5);case 'multi':return c.mode==='lines'&&lines>=2;case 'four':return c.mode==='lines'&&lines>=4;case 'cascade3':return c.cascades>=3;case 'cascade5':return c.cascades>=5;case 'comeback':return c.misses>=3;case 'small':return multiple<1;}}
/** Bonuses never modify RNG, tiers, base ticket accrual or one another. Residuals carry. */
for(const [i,pet]of Array.from(petCatalog.entries())){if(costumePerks[pet.id])continue;const conditions:PerkCondition[]=['hit','streak2','streak3','big','super','mega','amazing','cascade3','cascade5','comeback'];const condition=conditions[i%conditions.length];costumePerks[pet.id]={condition,currency:i%2?'tickets':'coins',bps:i%2?1000+(i%4)*500:condition==='hit'?100:200+(i%5)*100};}
// Ticket perks use the same final-multiple ticket base as the paid round.
for(const perk of Object.values(costumePerks))if(perk.currency==='tickets'&&perk.condition==='small')perk.condition='big';
// Regular tiers: 0.05/0.10/0.15/0.20%; conditional event tiers: 0.30/0.40%.
for(const perk of Object.values(costumePerks))if(perk.currency==='coins')perk.bps=eventCoinConditions.has(perk.condition)?(perk.bps>=500?EVENT_COIN_BPS:30):Math.min(NORMAL_COIN_BPS,Math.max(5,Math.ceil(perk.bps/100)*5));
// Each active part offers one top regular item that applies on every hit.
for(const slot of activePerkSlots){const candidates=Object.entries(costumePerks).filter(([id,perk])=>perkSlots[id]===slot&&perk.currency==='coins'&&!eventCoinConditions.has(perk.condition));const best=candidates.sort((a,b)=>b[1].bps-a[1].bps||a[0].localeCompare(b[0]))[0];if(best){best[1].condition='hit';best[1].bps=NORMAL_COIN_BPS;}}
export function resolvePerks(equipment:Partial<Record<string,string>>,context:PerkContext,remainders:Record<string,number>,ticketRewards=true){
 const awards:PerkAward[]=[],next={...remainders},eligible=equippedPerks(equipment).filter(({perk})=>matches(perk.condition,context)&&(perk.currency==='coins'||ticketRewards));
 const event=eligible.some(({perk})=>perk.currency==='coins'&&eventCoinConditions.has(perk.condition));
 let coinsLeft=Math.floor(context.payout*(event?EVENT_COIN_CAP_BPS:NORMAL_COIN_CAP_BPS)/10000),normalCoinsLeft=Math.floor(context.payout*NORMAL_COIN_CAP_BPS/10000);
 for(const {id,perk} of eligible){
  const coin=perk.currency==='coins',normal=coin&&!eventCoinConditions.has(perk.condition),divisor=10000;
  // Only sub-coin fractions carry. A clipped bonus is not a debt payable on later hits.
  const residual=coin?(next[id]||0)%divisor:(next[id]||0),raw=residual+(coin?context.payout:winTickets(context.payout,context.bet))*perk.bps;
  const available=coin?Math.min(coinsLeft,normal?normalCoinsLeft:coinsLeft):Number.MAX_SAFE_INTEGER,paid=Math.min(available,Math.floor(raw/divisor));
  next[id]=coin?raw%divisor:raw-paid*divisor;if(coin){coinsLeft-=paid;if(normal)normalCoinsLeft-=paid;}
  awards.push({id,condition:conditionNames[perk.condition],coins:coin?paid:0,tickets:coin?0:paid,pending:paid===0});
 }
 return {awards,remainders:next,coins:awards.reduce((n,a)=>n+a.coins,0),tickets:awards.reduce((n,a)=>n+a.tickets,0)};
}
