/** Viking Runecraft (2017), provider help at total stake 1.00.
 * Source transcription: docs/slots/viking-runecrafty-reference.json.
 * Ordinary-only evaluator: WILD overlap and feature geometry still require
 * source verification. This is not a registered/complete slot engine. */
export const VIKING_SIZE = 7;
export const VIKING_MIN_CLUSTER = 5;
export const VIKING_SYMBOLS = [
 'hammer','helmet','axe','amulet','rune-red','rune-yellow',
 'rune-blue','rune-purple','rune-green',
] as const;
export const VIKING_THRESHOLDS = [5,6,7,8,9,10,12,15] as const;
/** Multiples of TOTAL stake; never multiply by cell count or divide by lines. */
export const VIKING_PAYS = [
 [5,7.5,10,15,25,75,250,1000],
 [2.5,4,5,8,10,25,100,250],
 [1.5,2,3,4,7,15,50,100],
 [1,1.5,2,3,5,10,40,80],
 [.8,1,1.5,2,4,7,25,50],
 [.5,.8,1,1.5,3,6,20,40],
 [.4,.5,.8,1,2,5,15,30],
 [.3,.4,.5,.8,1.5,4,10,20],
 [.2,.3,.4,.5,1,2.5,5,10],
] as const;
export interface VikingOrdinaryAward {
 symbol:number;
 cells:number[];
 multiple:number;
 /** Unrounded base award; final wallet policy belongs to round settlement. */
 amount:number;
}
export function vikingOrdinaryClusters(board:readonly number[],bet:number):VikingOrdinaryAward[]{
 if(board.length!==49 || board.some(s=>!Number.isInteger(s)||s<0||s>=VIKING_SYMBOLS.length)
   || !Number.isSafeInteger(bet)||bet<=0) {
  throw Error('Viking ordinary evaluator requires 7x7 ordinary symbols and positive integer stake; special symbols need the dedicated feature evaluator');
 }
 const seen=new Set<number>();
 const awards:VikingOrdinaryAward[]=[];
 for(let start=0;start<board.length;start++){
  if(seen.has(start))continue;
  const symbol=board[start];
  const cells=[start];seen.add(start);
  for(let head=0;head<cells.length;head++){
   const cell=cells[head],x=cell%7,y=Math.floor(cell/7);
   const neighbours=[...(x>0?[cell-1]:[]),...(x<6?[cell+1]:[]),...(y>0?[cell-7]:[]),...(y<6?[cell+7]:[])];
   for(const next of neighbours){
    if(!seen.has(next)&&board[next]===symbol){seen.add(next);cells.push(next);}
   }
  }
  if(cells.length<VIKING_MIN_CLUSTER)continue;
  let tier=0;
  while(tier+1<VIKING_THRESHOLDS.length && cells.length>=VIKING_THRESHOLDS[tier+1])tier++;
  const multiple=VIKING_PAYS[symbol][tier];
  awards.push({symbol,cells:cells.sort((a,b)=>a-b),multiple,amount:bet*multiple});
 }
 return awards;
}
